module password_recovery (\n    input clk,\n    input rst_n,\n    input start,\n    \n    // Configuration\n    input [7:0] K,          // Iterations (1-256)\n    input [3:0] M,          // Queries (1-8)\n    \n    // Data loading interface\n    input load_en,\n    input [4:0] load_addr,  // 0-15=S, 16-41=T[0-25]\n    input [7:0] load_data,\n    input [3:0] load_len,   // Length for current entity\n    \n    // Query loading\n    input query_load_en,\n    input [2:0] query_addr,\n    input [31:0] query_pos,\n    \n    // Results\n    output reg [7:0] result_char,\n    output reg [2:0] result_addr,\n    output reg result_valid,\n    output reg done,\n    output reg error\n);\n\n// Memory arrays\nreg [7:0] S [0:15];\nreg [3:0] S_len;\nreg [7:0] T [0:25][0:7];\nreg [3:0] T_len [0:25];\nreg [31:0] query_pos_arr [0:7];\nreg [7:0] results [0:7];\n\n// Length table: length_table[c][k] = length of expanding char c k times\nreg [31:0] length_table [0:25][0:256];\n\n// State machine\nreg [3:0] state;\nlocalparam [3:0] IDLE = 4'd0, PRECOMP = 4'd1, PRECOMP_LOOP = 4'd2, PRECOMP_SUM = 4'd3;\nlocalparam [3:0] COMPUTE = 4'd4, FIND_CHAR = 4'd5, UPDATE = 4'd6, OUTPUT = 4'd7, DONE = 4'd8;\n\n// Processing registers\nreg [7:0] cur_q, cur_level, cur_char;\nreg [31:0] cur_pos, cumulative;\nreg [3:0] cur_len, idx;\nreg [7:0] cur_str [0:7];  // Max expansion length\nreg [7:0] pc, pl;        // Precompute counters\nreg [7:0] pi;            // Precomputation inner counter\nreg [31:0] temp_sum;\ninteger i;              // Loop index\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        // Initialize ALL registers\n        state <= IDLE;\n        done <= 1'b0;\n        error <= 1'b0;\n        result_valid <= 1'b0;\n        result_addr <= 3'd0;\n        result_char <= 8'd0;\n        cur_q <= 8'd0;\n        cur_level <= 8'd0;\n        cur_char <= 8'd0;\n        cur_len <= 4'd0;\n        idx <= 4'd0;\n        cur_pos <= 32'd0;\n        cumulative <= 32'd0;\n        pc <= 8'd0;\n        pl <= 8'd0;\n        pi <= 8'd0;\n        temp_sum <= 32'd0;\n        S_len <= 4'd0;\n        \n        // Initialize arrays\n        for (i = 0; i < 16; i = i + 1) S[i] <= 8'd0;\n        for (i = 0; i < 8; i = i + 1) results[i] <= 8'd0;\n        for (i = 0; i < 8; i = i + 1) query_pos_arr[i] <= 32'd0;\n        for (i = 0; i < 8; i = i + 1) cur_str[i] <= 8'd0;\n        \n        for (i = 0; i < 26; i = i + 1) begin\n            T_len[i] <= 4'd0;\n            for (integer j = 0; j < 8; j = j + 1) T[i][j] <= 8'd0;\n            for (integer k = 0; k < 257; k = k + 1) length_table[i][k] <= 32'd0;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                error <= 1'b0;\n                result_valid <= 1'b0;\n                \n                if (load_en) begin\n                    if (load_addr < 5'd16) begin\n                        S[load_addr] <= load_data;\n                        if (load_addr == 5'd15) S_len <= load_len;\n                    end else if (load_addr >= 5'd16 && load_addr < 5'd42) begin\n                        integer char_idx = load_addr - 5'd16;\n                        integer char_pos = load_len[2:0];\n                        T[char_idx][char_pos] <= load_data;\n                        T_len[char_idx] <= load_len[7:4];\n                    end\n                end\n                \n                if (query_load_en) begin\n                    query_pos_arr[query_addr] <= query_pos;\n                end\n                \n                if (start && load_addr == 5'd41) begin\n                    if (S_len == 4'd0 || K == 8'd0 || K > 8'd255 || M == 4'd0 || M > 4'd8) begin\n                        error <= 1'b1;\n                        state <= DONE;\n                    end else begin\n                        cur_q <= 8'd0;\n                        pc <= 8'd0;\n                        pl <= 8'd0;\n                        state <= PRECOMP;\n                    end\n                end\n            end\n            \n            PRECOMP: begin\n                if (pc < 8'd26) begin\n                    length_table[pc][8'd0] <= 32'd1;\n                    pc <= pc + 8'd1;\n                end else begin\n                    pc <= 8'd0;\n                    pl <= 8'd1;\n                    state <= (K > 8'd0) ? PRECOMP_LOOP : COMPUTE;\n                end\n            end\n            \n            PRECOMP_LOOP: begin\n                if (pl <= K) begin\n                    if (pc < 8'd26) begin\n                        temp_sum <= 32'd0;\n                        pi <= 8'd0;\n                        state <= PRECOMP_SUM;\n                    end else begin\n                        pc <= 8'd0;\n                        pl <= pl + 8'd1;\n                    end\n                end else begin\n                    state <= COMPUTE;\n                end\n            end\n            \n            PRECOMP_SUM: begin\n                if (pi < T_len[pc]) begin\n                    temp_sum <= temp_sum + length_table[T[pc][pi]][pl-8'd1];\n                    pi <= pi + 8'd1;\n                end else begin\n                    length_table[pc][pl] <= temp_sum;\n                    pc <= pc + 8'd1;\n                    state <= PRECOMP_LOOP;\n                end\n            end\n            \n            COMPUTE: begin\n                if (cur_q < M) begin\n                    cur_level <= K;\n                    cur_len <= S_len;\n                    cur_pos <= query_pos_arr[cur_q];\n                    for (i = 0; i < 8; i = i + 1) begin\n                        cur_str[i] <= (i < S_len) ? S[i] : 8'd0;\n                    end\n                    state <= FIND_CHAR;\n                end else begin\n                    state <= OUTPUT;\n                end\n            end\n            \n            FIND_CHAR: begin\n                if (cur_level == 8'd0) begin\n                    if (cur_pos > 32'd0 && cur_pos <= cur_len) begin\n                        results[cur_q] <= cur_str[cur_pos-1];\n                        cur_q <= cur_q + 8'd1;\n                        state <= COMPUTE;\n                    end else begin\n                        error <= 1'b1;\n                        state <= DONE;\n                    end\n                end else begin\n                    cumulative <= 32'd0;\n                    idx <= 4'd0;\n                    state <= UPDATE;\n                end\n            end\n            \n            UPDATE: begin\n                if (idx < cur_len) begin\n                    cur_char <= cur_str[idx];\n                    if (cur_pos <= cumulative + length_table[cur_str[idx]][cur_level]) begin\n                        cur_pos <= cur_pos - cumulative;\n                        cur_len <= T_len[cur_str[idx]];\n                        for (i = 0; i < 8; i = i + 1) begin\n                            cur_str[i] <= (i < T_len[cur_str[idx]]) ? T[cur_str[idx]][i] : 8'd0;\n                        end\n                        cur_level <= cur_level - 8'd1;\n                        state <= FIND_CHAR;\n                    end else begin\n                        cumulative <= cumulative + length_table[cur_str[idx]][cur_level];\n                        idx <= idx + 4'd1;\n                    end\n                end else begin\n                    error <= 1'b1;\n                    state <= DONE;\n                end\n            end\n            \n            OUTPUT: begin\n                if (result_addr < M) begin\n                    result_char <= results[result_addr];\n                    result_valid <= 1'b1;\n                    result_addr <= result_addr + 3'd1;\n                end else begin\n                    result_valid <= 1'b0;\n                    done <= 1'b1;\n                    state <= DONE;\n                end\n            end\n            \n            DONE: begin\n                if (!start) begin\n                    state <= IDLE;\n                    done <= 1'b0;\n                    result_addr <= 3'd0;\n                end\n            end\n            \n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule